import json
import numpy as np
import pandas as pd

DATA_FILE = "/home/chs/Work/tga_plot/tests/inputs/korean_excel.csv"

# Korean CSV files are often saved as CP949/EUC-KR rather than UTF-8.
df = None
last_error = None
for encoding in ("cp949", "euc-kr", "utf-8-sig", "utf-8"):
    try:
        df = pd.read_csv(DATA_FILE, encoding=encoding)
        break
    except UnicodeDecodeError as exc:
        last_error = exc
if df is None:
    raise last_error

df.columns = [str(column).strip() for column in df.columns]

x_col = "온도(°C)"
mass_col = "무게(%)"
derivative_col = "미분무게(%/°C)"

for column in (x_col, mass_col, derivative_col):
    if column not in df.columns:
        raise ValueError(f"필수 열을 찾을 수 없습니다: {column}")

for column in (x_col, mass_col, derivative_col):
    df[column] = pd.to_numeric(df[column], errors="coerce")

df = df[[x_col, mass_col, derivative_col]].dropna().sort_values(x_col)
x = df[x_col].to_numpy(dtype=float)
mass = df[mass_col].to_numpy(dtype=float)
derivative = df[derivative_col].to_numpy(dtype=float)

option = {
    "animation": False,
    "backgroundColor": "#ffffff",
    "textStyle": {
        "fontFamily": "Noto Sans CJK KR, sans-serif",
        "color": "#222222"
    },
    "title": {
        "text": "열중량 분석 (TGA)",
        "left": "center",
        "top": 12,
        "textStyle": {"fontSize": 18, "fontWeight": "bold"}
    },
    "tooltip": {
